/* T14 收藏印记：事件是权威数据，impressions 只是可重建缓存。
   本模块不依赖 DOM / 素材 data URI，Node 测试和浏览器共用同一套派生规则。 */
(function (root) {
    'use strict';

    const CATEGORY_ORDER = ['party', 'route', 'dorm', 'phone', 'room', 'other'];
    const CATEGORY_LABELS = { party: '聚会', route: '离场', dorm: '家里', phone: '手机', room: '房间', other: '其他' };
    const FOOD_LABELS = { cookie: '饼干', bread: '面包', chips: '薯片', chocolate: '巧克力', fruit: '水果', drink: '饮料' };
    const SONG_LABELS = { night: '晚风慢慢', walk: '放学以后', rain: '窗边小雨' };
    const CLIP_LABELS = { cat_box: '猫钻纸箱', cloud: '夜云让出月亮', pudding: '布丁晃三下', paperboat: '纸船慢慢出发', hamster: '抱紧这颗瓜子', warmtea: '热茶冒出一颗心' };
    const FORWARD_ASSETS = { cat_box: 'clip_cat_01', cloud: 'clip_night_01', pudding: 'clip_pudding_01', paperboat: 'clip_paperboat_01', hamster: 'clip_hamster_01', warmtea: 'clip_warmtea_01' };
    const CONTACT_LABELS = { friend: '朋友', partner: '对象' };
    const REST_LABELS = { corner: '角落歇一会', sofa: '沙发靠坐', nap: '沙发打盹' };
    const CHAT_LABELS = { ayao: '和阿遥聊天', sofa: '沙发闲聊', new: '认识新话题' };
    const ATTENTION_LABELS = { listen: '先听完再回', multi: '同时顾两边', pause: '说明后回消息' };
    const GAME_LABELS = { werewolf: '狼人杀', monopoly: '大富翁', cards: '斗地主', generic: '桌游一局' };

    const STAMP = (label, category, assetId, extra = {}) => ({ label, category, assetId, fallbackAsset: assetId, ...extra });

    const REGISTRY = {
        'party.game.werewolf': STAMP('狼人杀', 'party', 'stamp_werewolf'),
        'party.game.monopoly': STAMP('大富翁', 'party', 'stamp_monopoly'),
        'party.game.cards': STAMP('斗地主', 'party', 'stamp_cards'),
        'party.game.generic': STAMP('桌游一局', 'party', 'stamp_cards'),
        'party.book.prose': STAMP('翻几页散文', 'party', 'stamp_prose'),
        'party.book.picture': STAMP('看看画册', 'party', 'stamp_picture'),
        'party.book.major': STAMP('翻翻专业书', 'party', 'stamp_major'),
        'party.rest.corner': STAMP('角落歇一会', 'party', 'stamp_corner'),
        'party.rest.sofa': STAMP('沙发靠坐', 'party', 'stamp_sofa'),
        'party.rest.nap': STAMP('沙发打盹', 'party', 'stamp_nap'),
        'party.chat.ayao': STAMP('和阿遥聊天', 'party', 'stamp_chat_ayao'),
        'party.chat.sofa': STAMP('沙发闲聊', 'party', 'stamp_chat_sofa'),
        'party.chat.new': STAMP('认识新话题', 'party', 'stamp_chat_topic'),
        'party.attention.listen': STAMP('先听完再回', 'party', 'stamp_listen'),
        'party.attention.multi': STAMP('同时顾两边', 'party', 'stamp_multitask'),
        'party.attention.pause': STAMP('说明后回消息', 'party', 'stamp_pause'),
        'party.dinner': STAMP('一起吃饭', 'party', 'stamp_noodles'),
        'party.leave': STAMP('活动告别', 'party', 'stamp_goodbye'),
        'party.leave.table': STAMP('饭桌告别', 'party', 'stamp_leave_table'),
        'party.leave.game': STAMP('收起桌游', 'party', 'stamp_leave_game'),
        'route.early': STAMP('门口挥手', 'route', 'stamp_goodbye'),
        'route.walk': STAMP('散步后回去', 'route', 'stamp_walk'),
        'route.late': STAMP('夜宵后回去', 'route', 'stamp_night_noodles'),
        'dorm.task': STAMP('材料整理', 'dorm', 'stamp_task'),
        'dorm.gaming': STAMP('推岩石', 'dorm', 'stamp_gaming'),
        'dorm.music': STAMP('听歌', 'dorm', 'stamp_music'),
        'dorm.music.night': STAMP('晚风慢慢', 'dorm', 'stamp_music', { badgeAsset: 'playlist_night' }),
        'dorm.music.walk': STAMP('放学以后', 'dorm', 'stamp_music', { badgeAsset: 'playlist_walk' }),
        'dorm.music.rain': STAMP('窗边小雨', 'dorm', 'stamp_music', { badgeAsset: 'playlist_rain' }),
        'dorm.rest': STAMP('陪猫歇一会', 'dorm', 'cat_idle_01', { fallbackAsset: 'stamp_rest' }),
        'dorm.snack': STAMP('随心三明治', 'dorm', 'sw_top', { fallbackAsset: 'stamp_snack' }),
        'dorm.sleep': STAMP('晚安入睡', 'dorm', 'stamp_sleep'),
        'phone.video': STAMP('刷到一段短片', 'phone', 'app_video'),
        'phone.call': STAMP('完成通话', 'phone', 'stamp_call'),
        'phone.call.friend': STAMP('和朋友通话', 'phone', 'stamp_call_friend'),
        'phone.call.partner': STAMP('和对象通话', 'phone', 'stamp_call_partner'),
        'phone.reply.happy': STAMP('开心回复', 'phone', 'stamp_reply_happy'),
        'phone.reply.tired': STAMP('疲惫回复', 'phone', 'stamp_reply_tired'),
        'phone.reply.later': STAMP('暂缓回复', 'phone', 'stamp_later'),
        'phone.reply.legacy': STAMP('给阿遥的消息', 'phone', 'stamp_reply'),
        'room.lamp': STAMP('灯光调适', 'room', 'stamp_lamp'),
        'room.curtain': STAMP('窗帘调适', 'room', 'stamp_curtain'),
        'other.generic': STAMP('今晚收藏', 'other', 'stamp_task')
    };

    const clipName = id => CLIP_LABELS[id] || '短片';
    const foodList = list => (Array.isArray(list) ? list.filter(x => FOOD_LABELS[x]).slice().sort() : []);
    const snackKey = list => foodList(list).join('+');
    const snackLabel = list => foodList(list).map(id => FOOD_LABELS[id]).join('+') || '零食拼盘';

    function describe(id, detail = {}) {
        const raw = String(id || '');
        const known = REGISTRY[raw];
        if (known) {
            const item = { ...known, impressionId: raw, category: known.category || 'other' };
            if (raw === 'dorm.snack' && detail.activity === 'sandwich') {
                item.label = detail.recipeName || '随心三明治';
                const first = (Array.isArray(detail.layers) ? detail.layers : []).find(layer => ['egg','bacon','lettuce','tomato','cheese','mushroom','sauce'].includes(layer?.id));
                if (first) item.badgeAsset = 'sw_' + first.id;
            }
            if (raw === 'dorm.sleep' && Number.isInteger(detail.wakeMinuteOfDay)) {
                const wake = detail.wakeMinuteOfDay;
                item.label = `${String(Math.floor(wake / 60)).padStart(2, '0')}:${String(wake % 60).padStart(2, '0')}起床`;
            }
            return item;
        }
        if (raw.startsWith('dorm.snack.')) {
            const key = raw.slice('dorm.snack.'.length);
            const foods = foodList(key ? key.split('+') : []);
            return {
                impressionId: raw,
                label: snackLabel(foods),
                category: 'dorm',
                // 拼盘素材键用下划线（snack_bread_chips），收藏 ID 仍用加号组合键。
                assetId: foods.length ? 'snack_' + foods.join('_') : 'stamp_snack',
                fallbackAsset: 'stamp_snack',
                composition: foods
            };
        }
        if (raw.startsWith('dorm.music.')) {
            const song = raw.slice('dorm.music.'.length);
            return { impressionId: raw, label: SONG_LABELS[song] || '听歌', category: 'dorm', assetId: 'stamp_music', fallbackAsset: 'stamp_music', badgeAsset: SONG_LABELS[song] ? 'playlist_' + song : '' };
        }
        if (raw.startsWith('phone.forward.')) {
            const clip = raw.slice('phone.forward.'.length);
            return { impressionId: raw, label: `转发 · ${clipName(clip)}`, category: 'phone', assetId: FORWARD_ASSETS[clip] || ('clip_' + clip + '_01'), fallbackAsset: 'app_video', badgeAsset: 'stamp_share' };
        }
        if (raw.startsWith('phone.call.')) {
            const contact = raw.slice('phone.call.'.length);
            return { impressionId: raw, label: `和${CONTACT_LABELS[contact] || '熟悉的人'}通话`, category: 'phone', assetId: 'stamp_call', fallbackAsset: 'stamp_call' };
        }
        if (raw.startsWith('party.game.')) {
            const type = raw.slice('party.game.'.length);
            return { impressionId: raw, label: GAME_LABELS[type] || '桌游一局', category: 'party', assetId: type === 'werewolf' ? 'stamp_werewolf' : type === 'monopoly' ? 'stamp_monopoly' : 'stamp_cards', fallbackAsset: 'stamp_cards' };
        }
        return { impressionId: raw || 'other.generic', label: raw ? String(raw).split('.').slice(-1)[0] : '今晚收藏', category: 'other', assetId: 'stamp_task', fallbackAsset: 'stamp_task' };
    }

    function recordImpression(record) {
        const id = String(record?.id || '');
        const detail = record?.detail && typeof record.detail === 'object' ? record.detail : {};
        const map = {
            read: 'party.book.prose', readPicture: 'party.book.picture', readMajor: 'party.book.major',
            corner: 'party.rest.corner', sofaRest: 'party.rest.sofa', sofaNap: 'party.rest.nap',
            familiar: 'party.chat.ayao', sofaChat: 'party.chat.sofa', topic: 'party.chat.new',
            listen: 'party.attention.listen', multitask: 'party.attention.multi', pause: 'party.attention.pause',
            dinner: 'party.dinner', leaveTable: 'party.leave.table', leaveGame: 'party.leave.game', early: 'route.early', walk: 'route.walk', late: 'route.late',
            task: 'dorm.task', gaming: 'dorm.gaming', rest: 'dorm.rest', sleep: 'dorm.sleep',
            video: 'phone.video', scroll: 'phone.video', reply_later: 'phone.reply.later'
        };
        if (id === 'game' || id === 'gameLong') return { impressionId: detail.gameType && GAME_LABELS[detail.gameType] ? 'party.game.' + detail.gameType : 'party.game.generic', detail };
        if (id === 'sleep' && Number.isInteger(record?.wakeMinuteOfDay)) return { impressionId: 'dorm.sleep', detail: { ...detail, wakeMinuteOfDay: record.wakeMinuteOfDay } };
        if (id === 'music') return { impressionId: detail.songId && SONG_LABELS[detail.songId] ? 'dorm.music.' + detail.songId : 'dorm.music', detail };
        if (id === 'snack') {
            const consumed = foodList(detail.consumedFoodIds);
            return { impressionId: consumed.length ? 'dorm.snack.' + snackKey(consumed) : 'dorm.snack', detail: { ...detail, composition: consumed } };
        }
        if (id === 'call') return { impressionId: detail.contactId ? 'phone.call.' + detail.contactId : 'phone.call', detail };
        if (id === 'reply') return { impressionId: detail.branchKey === 'tired' || detail.branch === 'B' ? 'phone.reply.tired' : detail.branchKey === 'happy' || detail.branch === 'A' ? 'phone.reply.happy' : 'phone.reply.legacy', detail };
        return map[id] ? { impressionId: map[id], detail } : null;
    }

    function eventImpression(event) {
        const kind = String(event?.kind || '');
        if (!kind) return null;
        if (kind === 'sleep') return { impressionId: 'dorm.sleep', detail: event.detail || {} };
        if (kind === 'dorm.snack' && event.detail?.consumedFoodIds) {
            const key = snackKey(event.detail.consumedFoodIds);
            return { impressionId: key ? 'dorm.snack.' + key : 'dorm.snack', detail: { ...event.detail, composition: foodList(event.detail.consumedFoodIds) } };
        }
        if (kind === 'dorm.music' && event.detail?.songId) return { impressionId: 'dorm.music.' + event.detail.songId, detail: event.detail };
        return { impressionId: kind, detail: event.detail && typeof event.detail === 'object' ? event.detail : {} };
    }

    function addImpression(map, item, event) {
        if (!item || !item.impressionId) return;
        const at = Number.isFinite(event?.atGameMinute) ? event.atGameMinute : 0;
        const existing = map.get(item.impressionId);
        if (existing) {
            existing.quantity = item.impressionId === 'party.dinner' ? 1 : existing.quantity + 1;
            existing.lastAt = Math.max(existing.lastAt, at);
            existing.detail = item.detail || existing.detail;
            existing.sourceEventId = existing.sourceEventId || event?.eventId || '';
            existing.sourceRecordId = existing.sourceRecordId || event?.actionRecordId || '';
        } else {
            map.set(item.impressionId, {
                impressionId: item.impressionId,
                type: describe(item.impressionId, item.detail).category,
                optionId: item.impressionId,
                composition: item.detail?.composition || [],
                sourceEventId: event?.eventId || '',
                sourceRecordId: event?.actionRecordId || '',
                attemptId: event?.attemptId || '',
                quantity: 1,
                acquiredAt: at,
                lastAt: at,
                detail: item.detail || {},
                provenance: event?.provenance || 'played'
            });
        }
    }

    function deriveImpressions(events, records) {
        const map = new Map();
        const seen = new Set();
        const recordList = Array.isArray(records) ? records : [];
        // 旧版本把离开饭桌、收起桌游都记作“提前离席”，还会再次派生同一条行动。
        // 只修复收藏展示；原始行动记录、时间、电量与角色判定保持不变。
        const recordById = new Map(recordList.filter(Boolean).flatMap(record =>
            [record.commitId, record.attemptId].filter(Boolean).map(id => [id, record])));
        const eventList = (Array.isArray(events) ? events : []).map(event => {
            if (event?.kind !== 'party.leave') return event;
            const action = event.detail?.actionId || recordById.get(event.actionRecordId)?.id;
            const kind = action === 'leaveTable' ? 'party.leave.table' : action === 'leaveGame' ? 'party.leave.game' : 'party.leave';
            return { ...event, kind };
        });
        eventList.forEach(event => {
            if (!event || !event.eventId || seen.has(event.eventId)) return;
            seen.add(event.eventId);
            const item = eventImpression(event);
            if (item) addImpression(map, item, event);
        });
        const eventKinds = new Set(eventList.map(event => String(event?.kind || '')));
        const hasPrefix = prefix => [...eventKinds].some(kind => kind.startsWith(prefix));
        const covered = {
            'party.book': hasPrefix('party.book.'), 'party.rest': hasPrefix('party.rest.'), 'party.chat': hasPrefix('party.chat.'),
            'party.attention': hasPrefix('party.attention.'), 'party.game': hasPrefix('party.game.'), 'route': hasPrefix('route.'),
            'party.dinner': eventKinds.has('party.dinner'),
            'party.leave.table': eventKinds.has('party.leave.table'), 'party.leave.game': eventKinds.has('party.leave.game'),
            'dorm.task': eventKinds.has('dorm.task'), 'dorm.gaming': eventKinds.has('dorm.gaming'),
            'dorm.music': hasPrefix('dorm.music'), 'dorm.rest': eventKinds.has('dorm.rest'),
            'dorm.snack': hasPrefix('dorm.snack'), 'dorm.sleep': eventKinds.has('dorm.sleep') || eventKinds.has('sleep'),
            'phone.video': hasPrefix('phone.video'), 'phone.call': hasPrefix('phone.call.'),
            'phone.reply': hasPrefix('phone.reply.'), 'room.lamp': eventKinds.has('room.lamp'), 'room.curtain': eventKinds.has('room.curtain')
        };
        const skipRecord = record => {
            const id = record?.id;
            if (['read', 'readPicture', 'readMajor'].includes(id)) return covered['party.book'];
            if (['corner', 'sofaRest', 'sofaNap'].includes(id)) return covered['party.rest'];
            if (['familiar', 'sofaChat', 'topic'].includes(id)) return covered['party.chat'];
            if (['listen', 'multitask', 'pause'].includes(id)) return covered['party.attention'];
            if (['game', 'gameLong'].includes(id)) return covered['party.game'];
            if (id === 'dinner') return covered['party.dinner'];
            if (id === 'leaveTable') return covered['party.leave.table'];
            if (id === 'leaveGame') return covered['party.leave.game'];
            if (['early', 'walk', 'late'].includes(id)) return covered.route;
            if (id === 'task') return covered['dorm.task'];
            if (id === 'gaming') return covered['dorm.gaming'];
            if (id === 'music') return covered['dorm.music'];
            if (id === 'rest') return covered['dorm.rest'];
            if (id === 'snack') return covered['dorm.snack'];
            if (id === 'sleep') return covered['dorm.sleep'];
            if (id === 'video' || id === 'scroll') return covered['phone.video'];
            if (id === 'call') return covered['phone.call'];
            if (id === 'reply') return covered['phone.reply'];
            if (id === 'reply_later') return covered['phone.reply'];
            return false;
        };
        recordList.forEach((record, index) => {
            if (!record || skipRecord(record)) return;
            const item = recordImpression(record);
            if (!item) return;
            addImpression(map, item, {
                eventId: 'legacy:' + (record.commitId || record.attemptId || record.id + ':' + index),
                actionRecordId: record.commitId || record.attemptId || '',
                attemptId: record.attemptId || '',
                atGameMinute: Number.isFinite(record.time) ? record.time : 0,
                provenance: 'legacy_derived'
            });
        });
        return [...map.values()].sort((a, b) => b.lastAt - a.lastAt || a.impressionId.localeCompare(b.impressionId));
    }

    function autoSelection(impressions, limit = 12) {
        const list = Array.isArray(impressions) ? impressions : [];
        const max = Math.max(0, limit | 0);
        const buckets = CATEGORY_ORDER.map(category => list.filter(item => describe(item.impressionId, item.detail).category === category).sort((a, b) => b.lastAt - a.lastAt || a.impressionId.localeCompare(b.impressionId)));
        const selected = [];
        let round = 0;
        while (selected.length < max && buckets.some(bucket => bucket.length > round)) {
            buckets.forEach(bucket => { if (bucket[round] && selected.length < max) selected.push(bucket[round]); });
            round++;
        }
        return selected.sort((a, b) => a.acquiredAt - b.acquiredAt || a.impressionId.localeCompare(b.impressionId)).map(item => item.impressionId);
    }

    const api = { REGISTRY, CATEGORY_ORDER, CATEGORY_LABELS, FOOD_LABELS, SONG_LABELS, CLIP_LABELS, describe, deriveImpressions, autoSelection, snackKey, clipName };
    if (typeof module !== 'undefined' && module.exports) module.exports = api;
    root.DormImpressions = api;
})(typeof window === 'undefined' ? globalThis : window);


