    const left=clamp(x-pad,2,w-2),top=clamp(y-pad,2,h-2),right=clamp(x+button.offsetWidth+pad,left,w-2),bottom=clamp(y+button.offsetHeight+pad,top,h-2);
    function box(selector,bx,by,bw,bh){const el=$(selector,overlay);if(el)Object.assign(el.style,{left:bx+'px',top:by+'px',width:Math.max(0,bw)+'px',height:Math.max(0,bh)+'px'});}
