/* dorm-art.js */
/* 2026-11-14 宿舍近景像素美术：场景等比映射、无缩放 DOM 层、食品共同 unionBounds。
   只负责构图与素材，不接管任何玩法状态。 */
(function (root) {
    'use strict';
    const META = root.DORM_ART_META || { scenes: {}, sprites: {} };
    const ASSETS = root.DORM_ART_ASSETS || {};
    const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    const oldAssets = () => root.DORM_ASSETS || {};
    const oldMeta = () => root.DORM_ASSET_META?.sprites || {};
    function asset(id) { return ASSETS[id] || oldAssets()[id] || ''; }
    function clipMeta(id) { return META.clips?.[id] || null; }
    function shellMeta(id = 'phone_shell') { return META.shells?.[id] || null; }
    function meta(id) {
        const art = META.sprites?.[id];
        if (art) return { ...art, assetMap: 'art' };
        const old = oldMeta()[id];
        if (!old) return null;
        return {
            id,
            canvasSize: old.canvasSize || [old.contentBounds?.[2] || 0, old.contentBounds?.[3] || 0],
            contentBounds: old.contentBounds || [0, 0, old.canvasSize?.[0] || 0, old.canvasSize?.[1] || 0],
            visibleBounds: old.visibleBoundsAlpha16 || old.contentBounds,
            assetMap: 'dorm'
        };
    }
    function sceneMeta(id) { return META.scenes?.[id] || null; }
    function sceneSource(id) {
        const m = sceneMeta(id);
        const w = m?.sourceSize?.[0] || m?.width || 1536;
        const h = m?.sourceSize?.[1] || m?.height || 1024;
        return { w, h };
    }
    function rect(value) {
        if (Array.isArray(value)) return value.map(Number);
        if (typeof value === 'string') return value.split(',').map(Number);
        return [0, 0, 0, 0];
    }
    function appLocalRect(el) {
        const app = document.getElementById('app'), ar = app?.getBoundingClientRect(), b = el.getBoundingClientRect();
        if (!ar) return { x: b.left, y: b.top, w: b.width, h: b.height };
        if (!app.classList.contains('is-rotated')) return { x: b.left - ar.left, y: b.top - ar.top, w: b.width, h: b.height };
        const toLocal = (cx, cy) => ({ x: cy - ar.top, y: ar.right - cx });
        const pts = [toLocal(b.left, b.top), toLocal(b.right, b.top), toLocal(b.right, b.bottom), toLocal(b.left, b.bottom)];
        const xs = pts.map(p => p.x), ys = pts.map(p => p.y);
        const x0 = Math.min(...xs), y0 = Math.min(...ys);
        return { x: x0, y: y0, w: Math.max(...xs) - x0, h: Math.max(...ys) - y0 };
    }
    function appLocalPoint(e) {
        const app = document.getElementById('app'), b = app?.getBoundingClientRect();
        if (!b) return { x: e.clientX, y: e.clientY };
        return app.classList.contains('is-rotated')
            ? { x: e.clientY - b.top, y: b.right - e.clientX }
            : { x: e.clientX - b.left, y: e.clientY - b.top };
    }

    class SceneView {
        constructor(host, opts = {}) {
            this.host = host;
            this.opts = opts;
            this.sceneId = opts.sceneId || host.dataset.artScene || 'computer';
            const src = sceneSource(this.sceneId);
            this.sw = opts.sourceWidth || src.w;
            this.sh = opts.sourceHeight || src.h;
            this.sc = 1; this.ox = 0; this.oy = 0;
            host.classList.add('da-shell');
            host.dataset.artScene = this.sceneId;
            this.img = host.querySelector(':scope > .da-scene') || document.createElement('img');
            this.img.className = 'da-scene';
            this.img.alt = opts.alt || '';
            this.img.decoding = 'async';
            this.img.draggable = false;
            if (!this.img.parentElement) host.prepend(this.img);
            this.ui = host.querySelector(':scope > .da-ui') || document.createElement('div');
            this.ui.className = 'da-ui';
            if (!this.ui.parentElement) host.appendChild(this.ui);
            // 把直接子节点中的定位元素搬进 UI 层，保留已有 .da-ui 内容。
            [...host.children].forEach(child => {
                if (child === this.img || child === this.ui || child.classList?.contains('da-world')) return;
                if (child.hasAttribute?.('data-da-static')) return;
                this.ui.appendChild(child);
            });
            this.world = host.querySelector(':scope > .da-world') || document.createElement('div');
            this.world.className = 'da-world';
            if (!this.world.parentElement) host.insertBefore(this.world, this.ui);
            this.fore = null;
            const foreId = host.dataset.artForeground || opts.foreground;
            if (foreId) {
                this.fore = document.createElement('img');
                this.fore.className = 'da-scene da-foreground';
                this.fore.alt = '';
                this.fore.decoding = 'async';
                this.fore.draggable = false;
                this.fore.src = asset(foreId);
                host.insertBefore(this.fore, this.world);
            }
            this.errorEl = null;
            this.img.addEventListener('load', () => { this.host.classList.remove('da-loading'); this.host.classList.add('da-ready'); });
            this.img.addEventListener('error', () => this.fail());
            if (asset(this.sceneId)) {
                this.img.src = asset(this.sceneId);
                this.host.classList.add('da-loading');
            } else {
                this.fail();
            }
            this.refresh = this.refresh.bind(this);
            this.ro = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(this.refresh) : null;
            if (this.ro) this.ro.observe(host);
            window.addEventListener('resize', this.refresh);
            window.addEventListener('orientationchange', this.refresh);
            if (document.fonts?.ready) document.fonts.ready.then(this.refresh).catch(() => { });
            this.refresh();
            this.waitTries = 0;
            this.waitFrame = requestAnimationFrame(() => this.waitSize());
            this.placeFoods(host);
        }
        fail() {
            this.host.classList.add('da-load-error');
            this.host.classList.remove('da-loading');
            if (this.errorEl?.isConnected) return;
            this.errorEl = document.createElement('div');
            this.errorEl.className = 'da-load-fallback';
            this.errorEl.innerHTML = `<b>画面载入中</b><span>像素场景没有读出来，可以再试一次。</span><button type="button" class="da-subtle" data-da-retry>重试</button>`;
            this.errorEl.querySelector('[data-da-retry]').addEventListener('click', () => {
                this.host.classList.remove('da-load-error');
                this.host.classList.add('da-loading');
                const resources = root.GameResources;
                if (resources) resources.load(asset(this.sceneId), {priority:0}).then(src => { if (!this.disposed) this.img.src = src; }).catch(() => {});
                else this.img.src = asset(this.sceneId) + (asset(this.sceneId).includes('?') ? '&' : '?') + 'r=' + Date.now();
            });
            this.host.appendChild(this.errorEl);
        }
        waitSize() {
            if (!this.host.isConnected) return;
            const b = this.host.getBoundingClientRect();
            if (b.width > 4 && b.height > 4) { this.refresh(); this.host.dataset.artReady = '1'; return; }
            if (this.waitTries++ < 120) this.waitFrame = requestAnimationFrame(() => this.waitSize());
        }
        refresh() {
            const b = appLocalRect(this.host);
            const w = b.w || this.host.clientWidth || 1;
            const h = b.h || this.host.clientHeight || 1;
            const fit = this.opts.fit || this.host.dataset.artFit || 'cover';
            let sc, ox, oy;
            if (fit === 'contain') {
                // 让整张近景都进安全区，空白由 .da-shell 的同色夜底承接。
                sc = Math.min(w / this.sw, h / this.sh);
                ox = (w - this.sw * sc) / 2;
                oy = (h - this.sh * sc) / 2;
            } else if (fit === 'subject') {
                // 只保证声明的关键主体范围进入安全区，装饰性边角可以裁掉。
                const r = rect(this.opts.subjectBounds || this.host.dataset.artSubject || [0, 0, this.sw, this.sh]);
                sc = Math.min(w / Math.max(1, r[2]), h / Math.max(1, r[3]));
                ox = w / 2 - (r[0] + r[2] / 2) * sc;
                oy = h / 2 - (r[1] + r[3] / 2) * sc;
            } else {
                sc = Math.max(w / this.sw, h / this.sh);
            }
            // 近景源图顶部有安全边距；超宽短屏用 cover 会把屏幕顶栏裁掉。
            // 只对显式声明 safe-top 的玩法收一点比例，正常窗口不受影响。
            const safeTop = Number(this.host.dataset.artSafeTop || 0);
            if (safeTop > 0 && fit === 'cover') {
                const max = (h / 2 - 10) / (this.sh / 2 - safeTop);
                if (Number.isFinite(max) && max > 0) sc = Math.min(sc, max);
            }
            this.sc = sc;
            this.ox = fit === 'cover' ? (w - this.sw * sc) / 2 : ox;
            this.oy = fit === 'cover' ? (h - this.sh * sc) / 2 : oy;
            Object.assign(this.img.style, { left: this.ox + 'px', top: this.oy + 'px', width: this.sw * sc + 'px', height: this.sh * sc + 'px' });
            if (this.fore) Object.assign(this.fore.style, { left: this.ox + 'px', top: this.oy + 'px', width: this.sw * sc + 'px', height: this.sh * sc + 'px' });
            Object.assign(this.world.style, { left: this.ox + 'px', top: this.oy + 'px', width: this.sw + 'px', height: this.sh + 'px', transform: `scale(${sc})` });
            this.host.querySelectorAll('[data-da-rect]').forEach(el => {
                const r = rect(el.dataset.daRect);
                el.style.setProperty('--da-x', this.ox + r[0] * sc + 'px');
                el.style.setProperty('--da-y', this.oy + r[1] * sc + 'px');
                el.style.setProperty('--da-w', r[2] * sc + 'px');
                el.style.setProperty('--da-h', r[3] * sc + 'px');
                el.style.left = this.ox + r[0] * sc + 'px';
                el.style.top = this.oy + r[1] * sc + 'px';
                el.style.width = r[2] * sc + 'px';
                el.style.height = r[3] * sc + 'px';
            });
            this.host.classList.toggle('da-compact', h <= 540);
            this.host.dataset.scale = String(sc);
            this.host.dispatchEvent(new CustomEvent('da-resize', { detail: { sc, ox: this.ox, oy: this.oy } }));
        }
        placeFoods(scope = this.host) {
            scope.querySelectorAll('[data-da-food]').forEach(el => {
                const id = el.dataset.daFood, state = el.dataset.daState || 'sealed';
                paintFood(el, id, state);
            });
        }
        place(el, r) {
            r = rect(r);
            Object.assign(el.style, {
                left: this.ox + r[0] * this.sc + 'px', top: this.oy + r[1] * this.sc + 'px',
                width: r[2] * this.sc + 'px', height: r[3] * this.sc + 'px'
            });
            return el;
        }
        point(e) {
            const p = appLocalPoint(e), b = appLocalRect(this.host);
            return { x: (p.x - b.x - this.ox) / this.sc, y: (p.y - b.y - this.oy) / this.sc };
        }
        destroy() {
            this.disposed = true;
            this.ro?.disconnect();
            window.removeEventListener('resize', this.refresh);
            window.removeEventListener('orientationchange', this.refresh);
            cancelAnimationFrame(this.waitFrame);
        }
    }

    function upgrade(scope, opts) {
        if (!scope) return [];
        const hosts = scope.matches?.('[data-art-scene]') ? [scope] : [];
        scope.querySelectorAll?.('[data-art-scene]').forEach(host => { if (!hosts.includes(host)) hosts.push(host); });
        return hosts.map(host => {
            if (host.__daView) { host.__daView.refresh(); return host.__daView; }
            return (host.__daView = new SceneView(host, opts || {}));
        });
    }
    function destroy(scope) {
        if (!scope) return;
        scope.querySelectorAll?.('[data-art-scene]').forEach(host => { host.__daView?.destroy(); delete host.__daView; });
    }

    const foodCache = {};
    function foodFrame(id) {
        if (foodCache[id]) return foodCache[id];
        let union = null;
        ['sealed', 'open', 'bite', 'empty'].forEach(st => {
            const m = META.sprites?.[`food_${id}_${st}`];
            const b = m?.visibleBoundsAlpha16 || m?.contentBounds;
            if (!b) return;
            if (!union) union = b.slice();
            else {
                const x0 = Math.min(union[0], b[0]), y0 = Math.min(union[1], b[1]);
                const x1 = Math.max(union[0] + union[2], b[0] + b[2]);
                const y1 = Math.max(union[1] + union[3], b[1] + b[3]);
                union = [x0, y0, x1 - x0, y1 - y0];
            }
        });
        const m = META.sprites?.[`food_${id}_sealed`];
        const cell = m?.canvasSize || [256, 256];
        const frame = { union: union || [0, 0, cell[0], cell[1]], cell };
        foodCache[id] = frame;
        return frame;
    }
    function foodHTML(id, state = 'sealed', cls = '', alt = '') {
        const f = foodFrame(id);
        return `<span class="da-food ${cls}" data-da-food="${esc(id)}" data-da-state="${esc(state)}" style="--fw:${f.union[2]};--fh:${f.union[3]}" role="img" aria-label="${esc(alt || id)}"><img alt="" draggable="false" src="${asset(`food_${id}_${state}`)}" style="width:${(f.cell[0] / f.union[2] * 100).toFixed(4)}%;height:${(f.cell[1] / f.union[3] * 100).toFixed(4)}%;left:${(-f.union[0] / f.union[2] * 100).toFixed(4)}%;top:${(-f.union[1] / f.union[3] * 100).toFixed(4)}%"></span>`;
    }
    function paintFood(el, id, state) {
        if (!el) return;
        const f = foodFrame(id), img = el.querySelector('img');
        if (img) img.src = asset(`food_${id}_${state}`);
        el.dataset.daState = state;
        el.style.setProperty('--fw', f.union[2]);
        el.style.setProperty('--fh', f.union[3]);
    }
    function thumbHTML(id, h = 116, cls = '') {
        const m = meta(id);
        if (!m) return `<span class="da-thumb-fallback ${cls}">${esc(id)}</span>`;
        const c = m.contentBounds || [0, 0, m.canvasSize[0], m.canvasSize[1]];
        return `<span class="da-thumb ${cls}" style="--thumb-h:${h}px;--cw:${c[2]};--ch:${c[3]};--aw:${m.canvasSize[0]};--ah:${m.canvasSize[1]};--cx:${c[0]};--cy:${c[1]}"><img alt="" draggable="false" src="${asset(id)}" style="width:${(m.canvasSize[0] / c[2] * 100).toFixed(4)}%;height:${(m.canvasSize[1] / c[3] * 100).toFixed(4)}%;left:${(-c[0] / c[2] * 100).toFixed(4)}%;top:${(-c[1] / c[3] * 100).toFixed(4)}%"></span>`;
    }
    function portrait(charId, stateKey) {
        const index = root.DORM_PORTRAIT_INDEX, assets = root.DORM_PORTRAIT_ASSETS || {};
        const binding = index?.bindings?.[charId]?.[stateKey] || index?.bindings?.[charId]?.[index?.neutral?.[charId]];
        return binding && assets[binding] ? assets[binding] : '';
    }
    function foodLabel(id) {
        return { cookie: '饼干', bread: '面包', chips: '薯片', chocolate: '巧克力', fruit: '苹果', drink: '茶饮' }[id] || id;
    }
    function screenStyle(id) {
        const m = sceneMeta(id);
        return m?.screenRect || null;
    }
    root.DormArt = {
        META, ASSETS, asset, meta, sceneMeta, sceneSource, rect, upgrade, destroy,
        foodFrame, foodHTML, paintFood, foodLabel, thumbHTML, portrait, screenStyle,
        clipMeta, shellMeta,
        clip: id => asset(id),
        shell: id => asset(id),
        scene: (host, opts) => new SceneView(host, opts)
    };
})(typeof window === 'undefined' ? globalThis : window);


