        if (d.countRule !== 'entered_v6') for (const id of (d.completedSegmentIds || [])) if (/^seg:[1-6]$/.test(id)) progress[id.slice(4)] = 3000;
        progress[n] = Math.max(progress[n], clamp(Number(d.frontElapsedMs) || 0, 0, 3000));
