                const side = board.clientWidth / 4, vertical = drag.kind === 'rock' && st.rocks[drag.rock].axis === 'v', distance = vertical ? drag.dy : drag.dx;
                if (Math.abs(distance) < Math.max(12, side * .22)) { renderBoard(); return; }
                const amount = drag.kind === 'hero' ? Math.round(distance / side) || Math.sign(distance) : Math.sign(distance);
                const row = vertical ? clamp(drag.row + amount, 1, 3) : drag.row;
                const col = vertical ? drag.col : clamp(drag.col + amount, 1, 4);
