                    if (hero) kind = 'hero';
                    else if (rock >= 0) kind = 'rock';
                    else if (fixed) kind = 'fixed';
                    else if (door) kind = 'door';
                    if (fixed) cell.classList.add('is-fixed');
                    if (hero) cell.classList.add('is-hero');
                    if (rock >= 0) cell.classList.add('is-rock');
                    if (door) cell.classList.add('is-door');
                    if (st.sel?.type === 'rock' && st.sel.i === rock && rock >= 0) cell.classList.add('is-selected');
                    if (st.sel?.type === 'hero' && hero) cell.classList.add('is-selected');
                    const hot = st.sel?.type === 'rock' ? reachableCells(st.sel.i).some(x => x.r === rw && x.c === c)
                        : st.sel?.type === 'hero' ? heroReach().some(x => x.r === rw && x.c === c) : false;
