                const bottom = view.oy + (CAT_CALIB.placement[1] + CAT_CALIB.placement[3]) * view.sc;
                const cx = clamp(sourceCx, width / 2 + 12, b.width - width / 2 - 12);
                sprite.style.width = width + 'px';
                sprite.style.height = height + 'px';
                sprite.style.left = (cx - width / 2) + 'px';
                sprite.style.top = clamp(bottom - height, 24, b.height - height - 58) + 'px';
                layer.style.setProperty('--cat-w', width + 'px');
