                const point = view.point(e), left = (parseFloat(sprite.style.left) - view.ox) / view.sc, top = (parseFloat(sprite.style.top) - view.oy) / view.sc;
                return { x: (point.x - left) / Math.max(1, parseFloat(sprite.style.width) / view.sc), y: (point.y - top) / Math.max(1, parseFloat(sprite.style.height) / view.sc) };
