        if (!$('.sleep-alarm-shell')) return;
        sleepAlarmResize = fitSleepAlarmStage;
        window.addEventListener('resize', sleepAlarmResize);
        requestAnimationFrame(fitSleepAlarmStage);
        setTimeout(fitSleepAlarmStage, 80);
        setTimeout(fitSleepAlarmStage, 220);
