    async function finishSleep(bedtime, wake, closing) {
        if (window.GameResources && !GameResources.ready('report')) return GameResources.gate('report', () => finishSleep(bedtime, wake, closing), { key: 'finishSleep' });
        if (sleepCommitRunning || !state || state.done) return;
        sleepCommitRunning = true;
        try {
            const at = performance.now();
            const presentation = { roomBefore: captureSleepSnapshot(false, at), roomDark: captureSleepSnapshot(true, at), alarm: cloneSleepAlarm() };
            const p = commit(() => G.sleep(state, bedtime, wake, closing));
            if (!p) return;
            clearSleepAlarmFit();
            hideModal();
            const animate = !!window.BatteryTransition && !motionSeen();
            if (animate) { markMotionSeen(); window.BatterySfx?.unlock(); }
            // 母版还没解码完时先等一小会儿：音效与视觉同一刻起跑，角色出现时才能卡到 rolePop。
            if (animate && !window.BatterySfx?.bufferState?.master) {
                await Promise.race([
                    window.BatterySfx?.preload?.() || Promise.resolve(),
                    new Promise(resolve => setTimeout(resolve, 800))
                ]);
            }
            locked = true; keys = {}; joy = { x: 0, y: 0 };
            await runSleepPresentation(presentation);
            const view = showReport({deferReceiptGuide:animate});
            if (!animate || !view) { window.ReportView?.startHint?.(); return; }
            duckBgm();
            try {
                await window.BatteryTransition.play({
                    roleId: view.roleId,
                    roleName: NR.roles[view.roleId]?.name || '你的相处角色',
                    roleImage: NR.uri(view.roleId),
                    reportElement: view.report,
                    heroElement: view.hero,
                    ready: reportReady(view.hero),
                    focusElement: view.report.querySelector('#report-reading'),
                    onComplete: () => { locked = false; }
                });
            } catch (error) {
                console.warn('过渡演出未完成，已直接显示说明书。', error);
            } finally { restoreBgm(); locked = false; window.ReportView?.startReceiptGuide?.(); window.ReportView?.startHint?.(); }
        } finally { sleepCommitRunning = false; locked = false; }
    }
