    // 互动点开始前会留一份快照，因此完成小游戏后也能安全撤回并重新选择。
    function undo(skipPrompt = false) {
        if (!history.length) { toast('暂时没有可以撤回的行动。'); return; }
        const run = () => {
            const peek = history[history.length - 1];
            if (peek && window.GameResources) { const groups = GameBoot.sceneForSave(peek); if (!GameResources.ready(groups)) return GameResources.gate(groups, run, {key:'undo'}); }
            if (!peek) { toast('暂时没有可以撤回的行动。'); return; }
            stopServiceRuntime();
            activeDepartureSession = '';
            departureConfirmed = false;
            departureKeep = false;
            departureFinishing = false;
            visualSceneOverride = null;
            departureStage?.stop();
            const h = history.pop();
            const keepIntro = introducedScenes(), keepNear = { ...(uiBag().mobileNear || {}) };
            state = G.migrateSave(clone(h.state));
            if (state.departureStory) G.clearDepartureStory(state);
            uiBag().mobileIntroducedScenes = keepIntro;
            uiBag().mobileNear = keepNear;
            // 时间被撤回后，顶部时钟的基准也要跟着回退，避免之后新增时间不再提示。
            lastHudTime = null;
            pendingClockGain = 0;
            askedTimePreview = false;
            zoomed = !!h.zoomed;
            routePreview = state.route || 'early';
            warmPreview = !!state.warm;
            departureVars.route = routePreview;
            locked = false;
            showGame();
            setupScene();
            if (h.position && !P.blocked(state.scene, h.position.x, h.position.y)) Object.assign(player, h.position);
            save();
            hideModal();
            if (state.phase === 'arrival') intro();
            else if (state.phase === 'overlap') overlap();
            else { toast('已回到上一笔行动之前，电量和时间一起恢复。'); flushClockGain(); }
        };
        if (skipPrompt) { run(); return; }
        modal(`<span class="kicker">返回上一步</span><h2>撤回上一次已确认的行动？</h2><p>时间、电量、剧情进度和本局分类记录都会一起恢复。</p><div class="actions-row"><button id="doUndo" class="primary">返回上一步</button><button id="cancelUndo" class="secondary">保留当前安排</button></div>`);
        bind('doUndo', run);
        bind('cancelUndo', hideModal);
    }
